<?php

namespace App\Services;

use App\Models\Card;
use FPDF;
use Illuminate\Support\Facades\Storage;
use RuntimeException;
use setasign\Fpdi\Fpdi;

class CardPdfService
{
    private const PAGE_WIDTH = 567.0;
    private const PAGE_HEIGHT = 850.56;

    /*
     * Koordinat mengikuti template PDF 200 x 300 mm.
     * Bagian resmi (Banda Aceh, kepala dinas, nama, NIP) SUDAH ADA
     * DI TEMPLATE PDF, jadi jangan ditulis ulang oleh PHP.
     */

    private const PHOTO_X = 35.0;
    private const PHOTO_Y = 89.0;
    private const PHOTO_W = 56.0;
    private const PHOTO_H = 68.2;

    // Posisi mengikuti contoh yang Anda kirim:
    // stempel menumpuk pada sisi kanan foto dan signature menyilang ke kanan.
    private const STAMP_X = 91.5;
    private const STAMP_Y = 104.0;
    private const STAMP_W = 39.0;
    private const STAMP_H = 40.0;

    private const SIGN_X = 119.0;
    private const SIGN_Y = 119.5;
    private const SIGN_W = 45.0;
    private const SIGN_H = 27.0;

    // Gambar PNG transparan yang Anda kirim, ditanam di kode
    // supaya server tidak membutuhkan file Office / LibreOffice.
    private const STAMP_BASE64 = '';
    private const SIGNATURE_BASE64 = '';

    public function render(Card $card): string
    {
        $template = storage_path('app/templates/merge_nisn_2020.pdf');

        if (! is_file($template)) {
            throw new RuntimeException(
                'Template PDF tidak ditemukan di storage/app/templates/merge_nisn_2020.pdf.'
            );
        }

        $outputDir = storage_path('app/public/card_exports/pdf');
        if (! is_dir($outputDir) && ! mkdir($outputDir, 0777, true) && ! is_dir($outputDir)) {
            throw new RuntimeException('Folder PDF tidak dapat dibuat: ' . $outputDir);
        }

        $safeName = preg_replace('/[^A-Za-z0-9_-]+/', '-', $card->nama_lengkap ?: 'siswa') ?: 'siswa';
        $filename = 'kartu_' . $safeName . '_' . ($card->nisn ?: 'card') . '.pdf';
        $outputPath = $outputDir . DIRECTORY_SEPARATOR . $filename;

        $pdf = new Fpdi('P', 'pt', [self::PAGE_WIDTH, self::PAGE_HEIGHT]);
        $pdf->SetAutoPageBreak(false);
        $pdf->SetMargins(0, 0, 0);
        $pdf->SetCompression(true);

        if ($pdf->setSourceFile($template) < 1) {
            throw new RuntimeException('Template PDF tidak memiliki halaman.');
        }

        $templatePage = $pdf->importPage(1);

        $pdf->AddPage('P', [self::PAGE_WIDTH, self::PAGE_HEIGHT]);
        $pdf->useTemplate($templatePage, 0, 0, self::PAGE_WIDTH, self::PAGE_HEIGHT, true);

        /*
         * JANGAN menutup area data dengan Rect biru.
         * PDF template terbaru Anda sudah bersih dari placeholder $.
         * Menutup area dengan warna biru adalah penyebab kotak biru pada
         * versi sebelumnya.
         */

        $values = $this->values($card);

        // Nilai saja yang ditulis di ruang kosong template.
        $this->writeFitted($pdf, $values['nisn'], 102.5, 24.8, 70.0, 8.5);
        $this->writeFitted($pdf, $values['nama'], 102.5, 35.6, 70.0, 8.5);
        $this->writeFitted($pdf, $values['tempat_lahir'], 102.5, 46.4, 70.0, 8.5);
        $this->writeFitted($pdf, $values['tgl_lahir'], 102.5, 57.2, 70.0, 8.5);
        $this->writeFitted($pdf, $values['alamat'], 102.5, 67.9, 70.0, 8.0);
        $this->writeFitted($pdf, $values['jenis_kelamin'], 102.5, 78.7, 70.0, 8.5);

        // Foto.
        $photo = $this->photoPath($card);
        if ($photo) {
            $pdf->Image(
                $photo,
                self::PHOTO_X,
                self::PHOTO_Y,
                self::PHOTO_W,
                self::PHOTO_H
            );
        }

        // Stempel dan tanda tangan harus berada di atas foto.
        $stamp = $this->writeTempPng(self::STAMP_BASE64, 'sipena-stamp');
        $signature = $this->writeTempPng(self::SIGNATURE_BASE64, 'sipena-signature');

        try {
            if ($stamp) {
                $pdf->Image(
                    $stamp,
                    self::STAMP_X,
                    self::STAMP_Y,
                    self::STAMP_W,
                    self::STAMP_H
                );
            }

            if ($signature) {
                $pdf->Image(
                    $signature,
                    self::SIGN_X,
                    self::SIGN_Y,
                    self::SIGN_W,
                    self::SIGN_H
                );
            }
        } finally {
            if ($stamp && is_file($stamp)) {
                @unlink($stamp);
            }

            if ($signature && is_file($signature)) {
                @unlink($signature);
            }
        }

        $pdf->Output('F', $outputPath);

        return $outputPath;
    }

    private function values(Card $card): array
    {
        $alamat = trim(
            ($card->desa ? $card->desa . ', ' : '') .
            ($card->kecamatan ? $card->kecamatan . ', ' : '') .
            ($card->kabupaten ?? '')
        );

        return [
            'nisn' => (string) ($card->nisn ?? '-'),
            'nama' => (string) ($card->nama_lengkap ?? '-'),
            'tempat_lahir' => (string) ($card->tempat_lahir ?? '-'),
            'tgl_lahir' => optional($card->tanggal_lahir)->format('d-m-Y') ?? '-',
            'alamat' => $alamat !== '' ? $alamat : '-',
            'jenis_kelamin' => (string) ($card->jenis_kelamin ?? '-'),
        ];
    }

    private function photoPath(Card $card): ?string
    {
        if (! $card->foto_path || ! Storage::disk('public')->exists($card->foto_path)) {
            return null;
        }

        return Storage::disk('public')->path($card->foto_path);
    }

    private function writeTempPng(string $base64, string $prefix): ?string
    {
        $bytes = base64_decode($base64, true);

        if ($bytes === false || $bytes === '') {
            return null;
        }

        $path = storage_path('app/' . $prefix . '_' . uniqid('', true) . '.png');

        if (file_put_contents($path, $bytes) === false) {
            return null;
        }

        return $path;
    }

    private function writeFitted(
        FPDF $pdf,
        string $text,
        float $x,
        float $baselineY,
        float $maxWidth,
        float $size
    ): void {
        $text = trim($text);

        if ($text === '') {
            return;
        }

        $value = $this->latin1($text);

        for ($current = $size; $current >= 7.0; $current -= 0.25) {
            // Normal, bukan bold, agar lebih dekat ke teks template Word.
            $pdf->SetFont('Arial', '', $current);

            if ($pdf->GetStringWidth($value) <= $maxWidth) {
                $pdf->Text($x, $baselineY, $value);
                return;
            }
        }

        $pdf->SetFont('Arial', '', 7.0);
        $pdf->Text($x, $baselineY, $value);
    }

    private function latin1(string $text): string
    {
        return iconv('UTF-8', 'windows-1252//TRANSLIT//IGNORE', $text) ?: $text;
    }
}
